package org.example.domain;

import java.time.LocalDateTime;

/**
 * A user of the social network.
 * <p>
 * Lab 5: the id is generated by the storage (the database, or the repository for MEMORY
 * and FILE), so a new user is created without an id and receives it at save.
 */
public class Utilizator extends Entity<Long> {
    private final String username;
    private final String firstName;
    private final String lastName;
    private final LocalDateTime createdAt;

    /**
     * Creates a new user, without an id; the id is set by the repository at save.
     *
     * @param username unique name of the user
     * @param firstName first name
     * @param lastName last name
     * @param createdAt the moment the account was created
     */
    public Utilizator(String username, String firstName, String lastName, LocalDateTime createdAt) {
        this(null, username, firstName, lastName, createdAt);
    }

    /**
     * Creates a user that already has an id (e.g. read from a file or from the database).
     *
     * @param id id of the user (null if it is not generated yet)
     * @param username unique name of the user
     * @param firstName first name
     * @param lastName last name
     * @param createdAt the moment the account was created
     */
    public Utilizator(Long id, String username, String firstName, String lastName, LocalDateTime createdAt) {
        setId(id);
        this.username = username;
        this.firstName = firstName;
        this.lastName = lastName;
        this.createdAt = createdAt;
    }

    /**
     * @return the unique username
     */
    public String getUsername() {
        return username;
    }

    /**
     * @return the first name
     */
    public String getFirstName() {
        return firstName;
    }

    /**
     * @return the last name
     */
    public String getLastName() {
        return lastName;
    }

    /**
     * @return the moment the account was created
     */
    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    @Override
    public String toString() {
        return getId() + ": " + username + " (" + firstName + " " + lastName + "), cont creat pe "
                + createdAt.toLocalDate();
    }
}
